SELECT `id`, `tenant_id`, `campaign_id`, `script_flow_version_id`, `flow_node_key`, `contact_id`, `campaign_contact_key`, `phone`, `mode`, `status`, `attempts`, `max_attempts`, `last_error`, `human_agent_id`, `handoff_reason`, `recording_url`, `ai_session_id`, `telephony_call_id`, `telephony_line_id`, `gateway_node_id`, `gateway_endpoint`, `conversation_id`, `voice_ai_pipeline`, `last_transcript`, `summary`, `started_at`, `finished_at`, `next_attempt_at`, `created_at`, `updated_at` FROM `callsession`
WHERE `tenant_id` = #{tenantId,jdbcType=INTEGER}
ORDER BY `id` LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}

mapper.sql:
AND c.attempts=#{attempt} AND c.status IN ('ANSWERED','IN_AI')

  AND NOT EXISTS (SELECT 1 FROM realtimesession r WHERE r.tenant_id=#{tenantId}
    AND r.call_session_id=c.id AND COALESCE(r.turn_sequence,0)<>#{turnSequence})


  AND EXISTS (SELECT 1 FROM conversationstate s WHERE s.tenant_id=#{tenantId}
    AND s.call_id=c.id AND s.attempt=c.attempts AND s.generation=#{generation})

